/// <summary>
/// CoC extension for CB175: after a successful sales confirmation posting,
/// checks the customer 'ASN Required' flag and triggers the CCR check batch job.
/// </summary>
[ExtensionOf(classStr(SalesFormLetter_Confirm))]
final class METSalesFormLetter_Confirm_Extension
{
}

Method.Source:
public void run()
{
    next run();

    //ASN event should be trigger on Sales order confirmation 
    this.metTriggerCCRCheckIfRequired();
}

/// <summary>
/// Iterates the confirmed sales orders and, for each customer flagged as
/// 'ASN Required', triggers the CCR data check batch job.
/// </summary>
private void metTriggerCCRCheckIfRequired()
{
    SalesParmTable      salesParmTable;
    SalesTable          salesTable;
    CustTable           custTable;
    ParmId              parmId = this.parmId();

    if (!parmId)
    {
        return;
    }

    // Select sales orders that were posted in this run and whose customer
    // requires an ASN. Starting from SalesTable reduces record hops.
    while select salesTable
         exists join salesParmTable
            where salesParmTable.ParmId == parmId
               && salesParmTable.SalesId == salesTable.SalesId
        join custTable
            where custTable.AccountNum == salesTable.CustAccount
              && custTable.METASNRequired == NoYes::Yes
    {
        this.metRunCCRCheckBatch(salesTable);
    }
}

/// <summary>
/// Schedules the CCR check batch job for the given sales order.
/// </summary>
/// <param name = "_salesTable">The confirmed sales order.</param>
private void metRunCCRCheckBatch(SalesTable _salesTable)
{
    METCustomerASNProcessor     metCustomerASNProcessor = METCustomerASNProcessor::construct();
    metCustomerASNProcessor.processSalesOrder(_salesTable);
}
